@spec arrange_page_spec  src=tests/specs/arrange_page_spec.lua  loc=1166  cases=49
@exercises commandManager (h.cmgr), configManager (h.cm), arrangeManager (am)
@surface   cmgr:registerAll, cm:set, cmgr:push, am:tracksTakes, cmgr:invoke, cm:get, am:resizeTake, am:trimHead, am:trackSlots
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.SetMediaItemSelected, reaper:setCursor

# Intent
  Pin-tests for arrangePage's Page interface and arrange-scope edit commands.
  Cursor mechanics, off-screen no-op, and selection-precedence: arrange_view_spec.

# Helpers
  @fn newArrangePage(cm, ds, cmgr, chrome, gui)  @ 49-57
  @fn twoSelected(h)  @ 61-80
      -- Two instances of slot 0, one row each at QN 0 and 1, with rows 0..1 banded.
      -- The siblings at QN 10 and 20 are what slots 0 and 1 clone from.

# Cases
  @case 'bind / unbind are no-ops — arrange page never re-keys cm'  [harness]  @ 84-94
  @case 'the arrange facade enumerates the takes over a span of columns and QN'  [harness]  @ 100-129
  @case 'the arrange facade answers the placement a QN falls in on a track'  [harness]  @ 133-149
  @case 'focusState before any render returns both bits false'  [harness]  @ 153-160
  @case 'arrange-scope is registered at module load (cursorRight invokable)'  [harness]  @ 164-171
  @case 'arrange-scope place commands are registered (drop0/dropA/dropZ invokable)'  [harness]  @ 175-186
  @case 'a place-command drop advances the cursor by cm.arrangeAdvanceBy rows'  [harness]  @ 190-213
  @case 'arrangeAdvanceBy0..9 set cm.arrangeAdvanceBy at project tier'  [harness]  @ 217-228
  @case 'chained Super-D walks down — each clone becomes the selection for the next'  [harness]  @ 232-251
  @case 'a place-command drop inherits the length of an existing instance'  [harness]  @ 255-277
  @case 'arrangeNudgeForward moves the cursor take by one row'  [harness]  @ 281-295
  @case 'arrangeNudgeForward moves a take taller than one row'  [harness]  @ 299-314
  @case 'arrangeEdgeDown lengthens the cursor take by one row'  [harness]  @ 318-336
  @case 'growing a trimmed take moves its end, leaving the head where it was'  [harness]  @ 340-362
  @case 'arrangeEdgeDown silently no-ops at the take-source length cap'  [harness]  @ 366-381
  @case 'arrangeEdgeUp reduces the cursor take by one row'  [harness]  @ 385-401
  @case 'arrangeDeleteTake removes the cursor take'  [harness]  @ 405-419
  @case 'deleteSlot forever-deletes the cursor take\'s slot behind a confirm'  [harness]  @ 425-449
  @case 'deleteSlot no-ops with the cursor off every take'  [harness]  @ 453-469
  @case 'arrangeNudgeForward is a no-op when the next row is occupied'  [harness]  @ 473-489
  @case 'arrangeNudgeBack is a no-op when the take is already at row 0'  [harness]  @ 493-507
  @case 'arrangeEdgeDown against a flush neighbour stores intent; rendered is gap-capped'  [harness]  @ 511-530
  @case 'arrangeNudgeForward steps past a neighbour without a start-collision'  [harness]  @ 534-554
  @case 'arrangeNudgeForward truncates the displaced take when stepping past'  [harness]  @ 558-580
  @case 'arrangeDive switches to the tracker for the cursor MIDI take'  [harness]  @ 584-599
  @case 'createSlot dives the tracker onto the freshly-minted take'  [harness]  @ 603-618
  @case 'arrangeDive over an audio take still switches and restores (no take pinned)'  [harness]  @ 622-636
  @case 'arrangeDive over empty space switches and restores'  [harness]  @ 640-652
  @case 'the dive carries the caret QN, and carries none over empty space'  [harness]  @ 658-677
  @case 'kb edit acts on the cursor take when nothing is selected'  [harness]  @ 681-699
  @case 'kb delete no-ops when the cursor sits off every take'  [harness]  @ 703-721
  @case 'kb nudge no-ops when cursor sits on empty space'  [harness]  @ 725-742
  @case 'an edit command is a no-op when the cursor is over empty space'  [harness]  @ 746-761
  @case 'a second delete finds an empty cell under the cursor — no-op'  [harness]  @ 765-783
  @case 'seedCursorFromReaper lands the cursor on the selected take'  [harness]  @ 787-804
  @case 'seedCursorFromReaper falls back to the edit-cursor row'  [harness]  @ 808-822
  @case 'arrangeTakeProperties routes the focused MIDI take through the tracker facade'  [harness]  @ 831-844
  @case 'arrangeTakeProperties is a no-op on an audio take'  [harness]  @ 848-861
  @case 'arrangeDuplicateBelow drops a pooled clone at the focused take\'s append point'  [harness]  @ 865-881
  @case 'arrangeDuplicateBelow is silent for want of room and on audio takes'  [harness]  @ 885-903
  @case 'arrangeNextVariant past the last of the family swaps the target for a fresh variant'  [harness]  @ 907-938
  @case 'arrangeDuplicateBelow then arrangeNextVariant forks the copy onto a fresh slot'  [harness]  @ 944-968
  @case 'replace mode: a drop swaps the take under the cursor, keeping its start'  [harness]  @ 974-1001
  @case 'a replace with a selection held replaces every selected take'  [harness]  @ 1005-1022
  @case 'the replacements become the selection'  [harness]  @ 1026-1038
  @case 'a shorter replacement pulls the cursor back inside it'  [harness]  @ 1042-1070
  @case 'replace mode disarms on the drop it reinterprets — the next drop places'  [harness]  @ 1074-1102
  @case 'a cursor move disarms replace mode'  [harness]  @ 1106-1132
  @case 'a second arrangeReplaceMode disarms — the mode is a toggle'  [harness]  @ 1136-1163

